function observeScene(frame){
 if(!options.logVisible)return;
 const key=`${mode}:${liveSource}:${liveAttempt}:${liveVersion}:${stage}`;
 if(viewLog.key!==key){viewLog={key,hits:new Set(),time:-1,falls:0,recoveries:0,repeated:false,done:false};writeLog(`화면 · ${mode==='trace'?'학습 시도 장면 재생':liveSource==='best'?'통합 모델 실행':'최근 모델 실행'} · ${STAGES[stage].label}${mode==='trace'?' · 학습 계산과 별도로 재생 중':''}`);}
 if(frame.time<viewLog.time-.1&&!viewLog.repeated){writeLog('화면 · 같은 학습 장면을 반복 재생 중 · 새 관찰 장면이 도착하면 전환');viewLog.repeated=true;}
 for(const hit of frame.hits||[])if(!viewLog.hits.has(hit.id)){viewLog.hits.add(hit.id);writeLog(`화면 ${hit.time.toFixed(1)}초 · ${hitDescription(hit)}`);}
 const m=frame.metrics;if(m.falls>viewLog.falls){writeLog(`화면 ${frame.time.toFixed(1)}초 · 넘어짐 감지 · ${training&&mode==='trace'&&liveSource==='candidate'?'학습의 실패 경험으로 반영':'현재 모델의 대응 결과'}`);viewLog.falls=m.falls;}
 if(m.recoveries>viewLog.recoveries){writeLog(`화면 ${frame.time.toFixed(1)}초 · 다시 일어나 안정 자세 회복`);viewLog.recoveries=m.recoveries;}
 if(m.done&&!viewLog.done){writeLog(`화면 · ${m.terminationReason==='duration'?'설정한 실행 시간 완료':'시도 종료'}${training?' · 학습 계산은 계속 진행 중':''}`);viewLog.done=true;}
 const totals=rewardTotals(m);writeLog(`화면 ${frame.time.toFixed(1)}초 · ${m.recovering?'넘어진 상태':m.finalUpright?'서 있는 상태':'자세 변화 중'} · 목표 속도 ${(m.targetSpeed||0).toFixed(2)}m/s · 누적 보상 +${totals.positive.toFixed(1)} / 벌점 −${totals.negative.toFixed(1)}`,'scene-state',4000);
 viewLog.time=frame.time;
}

function hud(data){if(!data)return;const m=data.frame.metrics,score=rewardTotals(m);get('positive-total').textContent='+'+score.positive.toFixed(1);get('negative-total').textContent='−'+score.negative.toFixed(1);get('positive-bar').style.width=(score.positiveRatio*100)+'%';get('negative-bar').style.width=(score.negativeRatio*100)+'%';get('score-balance').setAttribute('aria-label',`현재 시도 보상 ${score.positive.toFixed(1)}점, 벌점 ${score.negative.toFixed(1)}점`);get('time').innerHTML=`${m.time.toFixed(1)}<small>초</small>`;get('distance').innerHTML=`${signed(m.distance)}<small>m</small>`;get('speed').innerHTML=`${m.speed.toFixed(1)}<small>m/s</small>`;observeScene(data.frame);

}

function animate(time){
 lastDraw=time;
 const dt=lastTime?Math.min(.05,(time-lastTime)/1000):0;lastTime=time;
 if(!viewPaused){if(mode==='live'&&live&&!liveRobots.every(w=>w.done)){accumulator+=dt;while(accumulator>=DT){previousFrames=currentFrames;for(const w of liveRobots)if(!w.done)w.step(liveWeights,false);currentFrames=liveRobots.map(w=>w.snapshot());accumulator-=DT;}if(liveRobots.every(w=>w.done)){viewPaused=true;controls();if(!training)status('관찰 종료 · 중간 관찰 또는 통합 모델 실행으로 다시 시작하세요.');}}else if(mode==='trace'){traceTime+=dt;if(pendingScene&&traceTime>=previewWindow(scene,stage))showRecent(pendingScene,true);}if(pushArrow){pushArrow.remaining-=dt;if(pushArrow.remaining<=0)pushArrow=null;}}
 const data=sourceFrame();draw(data);if(time-lastHud>140){hud(data);lastHud=time;}
 frame=requestAnimationFrame(animate);
}
